mapper.select:
SELECT id, user_id, acc_name, type, init_balance, balance, allow_overdraft, create_time
FROM account
WHERE id = #{id} AND user_id = #{userId}

SELECT id, user_id, acc_name, type, init_balance, balance, allow_overdraft, create_time
FROM account
WHERE user_id = #{userId} AND acc_name = #{accName}

mapper.update:
UPDATE account
SET acc_name = #{accName}, type = #{type}, allow_overdraft = #{allowOverdraft}
WHERE id = #{id} AND user_id = #{userId}

UPDATE account
SET balance = balance + #{delta}
WHERE id = #{accountId} AND user_id = #{userId}

UPDATE account
SET balance = balance + #{delta}
WHERE id = #{accountId} AND user_id = #{userId}
  AND (allow_overdraft = 1 OR balance + #{delta} >= 0)

UPDATE account
SET balance = #{balance}
WHERE id = #{accountId} AND user_id = #{userId}
